-- Honey Flowers loyalty program: Cloudflare D1 (SQLite) schema.
-- Translation of db/migrations/001_init.sql (PostgreSQL) with these rules:
--   * ids are TEXT (UUID strings generated by the Worker);
--   * money and points are INTEGER UZS (1 "мёд" = 1 сум), never REAL;
--   * timestamps are ISO-8601 UTC TEXT ("2026-11-01T05:00:00.000Z"), so they
--     sort lexicographically; calendar logic (Asia/Tashkent) lives in the engine;
--   * JSON columns are TEXT checked with json_valid().
-- D1 has no row locks: per-client optimistic concurrency uses client_versions
-- (see apps/worker/src/db/d1Repository.ts, saveOutcome).

-- ---------------------------------------------------------------- settings
-- Global key/value settings:
--   clock_offset_days  TEST_MODE time travel (now = real now + N days)
--   rules_version      id of the rules_versions row in force
--   public_url         Worker origin, stored by GET /setup
--   bot_username, bot_info  cached getMe result (stored by /setup / first webhook)
CREATE TABLE settings (
  key    TEXT PRIMARY KEY,
  value  TEXT NOT NULL
);
INSERT INTO settings (key, value) VALUES ('clock_offset_days', '0'), ('rules_version', '1');

-- ---------------------------------------------------------------- telegram users
-- Everyone who opened the bot or the Mini App (also before registration):
-- remembers the language and the display name (used for TEST_MODE actors).
CREATE TABLE tg_users (
  telegram_id    INTEGER PRIMARY KEY,
  first_name     TEXT,
  username       TEXT,
  language       TEXT NOT NULL DEFAULT 'ru' CHECK (language IN ('ru', 'uz', 'en')),
  first_seen_at  TEXT NOT NULL,
  last_seen_at   TEXT NOT NULL
);

-- ---------------------------------------------------------------- clients
CREATE TABLE clients (
  id                 TEXT PRIMARY KEY,
  telegram_id        INTEGER NOT NULL UNIQUE,
  code               TEXT NOT NULL UNIQUE,          -- "HF" + 4..6 digits, encoded in the QR as "HF:<code>"
  phone              TEXT UNIQUE,                   -- E.164, e.g. +998901234567
  name               TEXT,
  birthday           TEXT,                          -- YYYY-MM-DD
  language           TEXT NOT NULL DEFAULT 'ru' CHECK (language IN ('ru', 'uz', 'en')),
  consent_at         TEXT,
  -- LevelOverride in core: effective level = max(override, level from purchases after level_override_at).
  level_override     TEXT,
  level_override_at  TEXT,
  created_at         TEXT NOT NULL,
  CONSTRAINT clients_code_format CHECK (code GLOB 'HF[0-9][0-9][0-9][0-9]*' AND length(code) BETWEEN 6 AND 8),
  CONSTRAINT clients_phone_format CHECK (phone IS NULL OR (phone GLOB '+[0-9]*' AND length(phone) BETWEEN 10 AND 16)),
  CONSTRAINT clients_override_pair CHECK ((level_override IS NULL) = (level_override_at IS NULL))
);
CREATE INDEX clients_created_idx ON clients (created_at);

-- Optimistic concurrency: saveOutcome inserts (client_id, loadedVersion + 1)
-- as the FIRST statement of its batch. A concurrent writer that loaded the same
-- version violates the primary key and its whole batch is rolled back.
CREATE TABLE client_versions (
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  version     INTEGER NOT NULL CHECK (version >= 1),
  PRIMARY KEY (client_id, version)
);
-- Belt and braces: a version must be exactly max + 1, so a writer that loaded a
-- much older version cannot slip in even if old rows were ever pruned.
CREATE TRIGGER client_versions_sequential BEFORE INSERT ON client_versions
WHEN NEW.version <> (SELECT COALESCE(MAX(version), 0) + 1 FROM client_versions WHERE client_id = NEW.client_id)
BEGIN
  SELECT RAISE(ABORT, 'stale client version');
END;

-- ---------------------------------------------------------------- staff
CREATE TABLE staff (
  id           TEXT PRIMARY KEY,
  telegram_id  INTEGER UNIQUE,                 -- NULL until a staff member added by phone opens the app
  phone        TEXT UNIQUE,
  name         TEXT NOT NULL,
  role         TEXT NOT NULL CHECK (role IN ('florist', 'manager', 'owner')),
  active       INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  created_at   TEXT NOT NULL,
  CONSTRAINT staff_identity CHECK (telegram_id IS NOT NULL OR phone IS NOT NULL)
);

-- TEST_MODE only: role chosen by the tester (POST /api/test/role).
-- Effective role in TEST_MODE = this row (also 'client'), else active staff role, else 'client'.
-- Without TEST_MODE this table is ignored.
CREATE TABLE test_roles (
  telegram_id  INTEGER PRIMARY KEY,
  role         TEXT NOT NULL CHECK (role IN ('client', 'florist', 'manager', 'owner')),
  updated_at   TEXT NOT NULL
);

-- ---------------------------------------------------------------- rules
-- Versioned LoyaltyRules JSON (validated by the zod schema in packages/core).
-- settings.rules_version points to the version in force; every purchase keeps
-- the version it was computed with. Version 1 (defaultRules) is inserted by the
-- Worker on first use, so the JSON lives in one place (packages/core).
CREATE TABLE rules_versions (
  id           INTEGER PRIMARY KEY,           -- = rules.version
  rules        TEXT NOT NULL CHECK (json_valid(rules)),
  active_from  TEXT NOT NULL,
  created_by   TEXT,                          -- staff id / actor id
  created_at   TEXT NOT NULL,
  CONSTRAINT rules_versions_version_match CHECK (json_extract(rules, '$.version') = id)
);

-- ---------------------------------------------------------------- purchases
-- staff_id / reversed_by hold the acting staff id. In TEST_MODE a tester with a
-- switched role acts as "tg:<telegram_id>", so these columns have no FK to staff.
CREATE TABLE purchases (
  id                TEXT PRIMARY KEY,
  client_id         TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  staff_id          TEXT,
  amount            INTEGER NOT NULL CHECK (amount > 0),
  lines             TEXT NOT NULL CHECK (json_valid(lines) AND json_type(lines) = 'array' AND json_array_length(lines) > 0),
  channel           TEXT NOT NULL CHECK (channel IN ('store', 'delivery')),
  points_redeemed   INTEGER NOT NULL DEFAULT 0 CHECK (points_redeemed >= 0),
  discount_applied  INTEGER NOT NULL DEFAULT 0 CHECK (discount_applied >= 0),
  reward_used_id    TEXT,
  idempotency_key   TEXT NOT NULL UNIQUE,
  rules_version_id  INTEGER NOT NULL REFERENCES rules_versions(id),
  result            TEXT CHECK (result IS NULL OR json_valid(result)),  -- PurchaseSummary, returned on replay
  status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'reversed')),
  reversed_reason   TEXT,
  reversed_by       TEXT,
  reversed_at       TEXT,
  created_at        TEXT NOT NULL,
  CONSTRAINT purchases_paid_nonnegative CHECK (points_redeemed + discount_applied <= amount),
  CONSTRAINT purchases_reversal_fields CHECK (
    (status = 'active'   AND reversed_reason IS NULL AND reversed_at IS NULL) OR
    (status = 'reversed' AND reversed_reason IS NOT NULL AND length(trim(reversed_reason)) > 0 AND reversed_at IS NOT NULL)
  )
);
CREATE INDEX purchases_client_created_idx ON purchases (client_id, created_at);
CREATE INDEX purchases_created_idx ON purchases (created_at);

-- ---------------------------------------------------------------- points ledger
-- Append-only: balance = SUM(amount). Row order (rowid) = insertion order.
CREATE TABLE points_ledger (
  id               TEXT PRIMARY KEY,
  client_id        TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  type             TEXT NOT NULL CHECK (type IN ('accrual', 'redeem', 'expire', 'reversal', 'welcome', 'manual_adjust')),
  amount           INTEGER NOT NULL CHECK (amount <> 0),   -- signed
  purchase_id      TEXT REFERENCES purchases(id) ON DELETE CASCADE,
  staff_id         TEXT,
  reason           TEXT,
  idempotency_key  TEXT UNIQUE,                            -- standalone redeem / manual adjust
  created_at       TEXT NOT NULL,
  CONSTRAINT ledger_sign CHECK (
    (type IN ('accrual', 'welcome') AND amount > 0) OR
    (type IN ('redeem', 'expire') AND amount < 0) OR
    (type IN ('reversal', 'manual_adjust'))
  ),
  CONSTRAINT ledger_accrual_has_purchase CHECK (type NOT IN ('accrual', 'reversal') OR purchase_id IS NOT NULL),
  CONSTRAINT ledger_manual_has_reason CHECK (type <> 'manual_adjust' OR (staff_id IS NOT NULL AND reason IS NOT NULL))
);
CREATE INDEX points_ledger_client_idx ON points_ledger (client_id, created_at);
CREATE INDEX points_ledger_purchase_idx ON points_ledger (purchase_id) WHERE purchase_id IS NOT NULL;
CREATE INDEX points_ledger_created_idx ON points_ledger (created_at);
-- Welcome bonus at most once per client.
CREATE UNIQUE INDEX points_ledger_welcome_once ON points_ledger (client_id) WHERE type = 'welcome';

-- Append-only guard. Deleting is possible only inside a maintenance batch
-- (TEST_MODE POST /api/test/reset-me), which sets the 'allow_ledger_delete' flag.
CREATE TABLE maintenance (flag TEXT PRIMARY KEY);
CREATE TRIGGER points_ledger_no_update BEFORE UPDATE ON points_ledger
BEGIN
  SELECT RAISE(ABORT, 'points_ledger is append-only (use a reversal or manual_adjust entry)');
END;
CREATE TRIGGER points_ledger_no_delete BEFORE DELETE ON points_ledger
WHEN NOT EXISTS (SELECT 1 FROM maintenance WHERE flag = 'allow_ledger_delete')
BEGIN
  SELECT RAISE(ABORT, 'points_ledger is append-only (use a reversal or manual_adjust entry)');
END;

-- ---------------------------------------------------------------- honeycomb
CREATE TABLE card_moves (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,      -- order of moves matters (latest = current position)
  client_id    TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  purchase_id  TEXT REFERENCES purchases(id) ON DELETE CASCADE,
  cycle        INTEGER NOT NULL CHECK (cycle >= 1),
  cell         INTEGER NOT NULL CHECK (cell >= 0),     -- 0 = reset to an empty card
  reason       TEXT NOT NULL DEFAULT 'purchase' CHECK (reason IN ('purchase', 'expiry_reset')),
  reverted_at  TEXT,
  created_at   TEXT NOT NULL,
  CONSTRAINT card_moves_kind CHECK (
    (reason = 'purchase' AND purchase_id IS NOT NULL AND cell >= 1) OR
    (reason = 'expiry_reset' AND purchase_id IS NULL AND cell = 0)
  )
);
CREATE INDEX card_moves_client_idx ON card_moves (client_id, id);
CREATE UNIQUE INDEX card_moves_purchase_uq ON card_moves (purchase_id) WHERE reverted_at IS NULL AND purchase_id IS NOT NULL;
CREATE UNIQUE INDEX card_moves_cell_uq ON card_moves (client_id, cycle, cell) WHERE reverted_at IS NULL AND reason = 'purchase';

-- purchases.reward_used_id <-> rewards.*_purchase reference each other; to keep
-- inserts and TEST_MODE deletes simple these two links have no FK constraints.
CREATE TABLE rewards (
  id                    TEXT PRIMARY KEY,                -- '<cycle>-<cell>-<unlocking purchase id>' (core rewardId())
  client_id             TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  cycle                 INTEGER NOT NULL CHECK (cycle >= 1),
  cell                  INTEGER NOT NULL CHECK (cell >= 1),
  type                  TEXT NOT NULL CHECK (type IN ('free_card', 'free_delivery', 'discount_pct', 'custom')),
  value                 REAL,                            -- percent for discount_pct, cap in UZS for free_*
  title                 TEXT NOT NULL,
  status                TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'used', 'revoked')),
  unlocked_by_purchase  TEXT,
  used_in_purchase      TEXT,
  used_idempotency_key  TEXT UNIQUE,
  unlocked_at           TEXT NOT NULL,
  used_at               TEXT,
  CONSTRAINT rewards_used_fields CHECK ((status = 'used') = (used_at IS NOT NULL))
);
CREATE INDEX rewards_client_status_idx ON rewards (client_id, status);
-- Note: the Postgres schema has UNIQUE (client_id, cycle, cell) WHERE status <> 'revoked'.
-- It is dropped here: after reversing the latest purchase whose gift was already
-- used (gift kept as 'used', card rolled back), the next purchase legitimately
-- unlocks the same cycle/cell again.

-- ---------------------------------------------------------------- important dates
CREATE TABLE important_dates (
  id          TEXT PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  title       TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 100),
  month       INTEGER NOT NULL CHECK (month BETWEEN 1 AND 12),
  day         INTEGER NOT NULL CHECK (day BETWEEN 1 AND 31),
  created_at  TEXT NOT NULL,
  CONSTRAINT important_dates_valid_day CHECK (
    day <= CASE WHEN month = 2 THEN 29 WHEN month IN (4, 6, 9, 11) THEN 30 ELSE 31 END
  )
);
CREATE INDEX important_dates_md_idx ON important_dates (month, day);

-- ---------------------------------------------------------------- notifications
-- Engine dedupe keys (ClientState.sentNotificationKeys), e.g. 'expiry_warning:2026-11-01:7'.
CREATE TABLE notification_keys (
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  key         TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  PRIMARY KEY (client_id, key)
);

-- Every bot message the notifier sent (or tried to).
CREATE TABLE notifications_log (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  client_id    TEXT REFERENCES clients(id) ON DELETE CASCADE,
  telegram_id  INTEGER,
  types        TEXT NOT NULL,                 -- comma-separated LoyaltyEvent types
  text         TEXT NOT NULL,
  status       TEXT NOT NULL CHECK (status IN ('sent', 'failed', 'skipped')),
  error        TEXT,
  created_at   TEXT NOT NULL
);
CREATE INDEX notifications_log_created_idx ON notifications_log (created_at);

-- ---------------------------------------------------------------- views
CREATE VIEW client_balances AS
SELECT c.id AS client_id, COALESCE(SUM(l.amount), 0) AS balance
FROM clients c
LEFT JOIN points_ledger l ON l.client_id = c.id
GROUP BY c.id;
